import numpy as np

def get_cost(n, x, y):
    cost = 0
    for k in range(1, n // 2 + 1):
        cx_k = sum(x[i] * x[(i + k) % n] for i in range(n))
        cy_k = sum(y[i] * y[(i + k) % n] for i in range(n))
        cost += (cx_k + cy_k + 2)**2
    return cost

def solve_simulated_annealing(n, max_iter=100000):
    x = [1] * 12 + [-1] * 11
    y = [1] * 12 + [-1] * 11
    np.random.shuffle(x)
    np.random.shuffle(y)

    current_cost = get_cost(n, x, y)

    temp = 1.0
    cooling_rate = 0.99999

    for i in range(max_iter):
        if current_cost == 0:
            return x + y

        # Pick a random move
        if np.random.random() < 0.5:
            # Flip two bits in x to keep sum constant
            idx1, idx2 = np.random.choice(n, 2, replace=False)
            if x[idx1] != x[idx2]:
                x[idx1], x[idx2] = x[idx2], x[idx1]
                new_cost = get_cost(n, x, y)
                if new_cost < current_cost or np.random.random() < np.exp((current_cost - new_cost) / temp):
                    current_cost = new_cost
                else:
                    x[idx1], x[idx2] = x[idx2], x[idx1]
        else:
            # Flip two bits in y to keep sum constant
            idx1, idx2 = np.random.choice(n, 2, replace=False)
            if y[idx1] != y[idx2]:
                y[idx1], y[idx2] = y[idx2], y[idx1]
                new_cost = get_cost(n, x, y)
                if new_cost < current_cost or np.random.random() < np.exp((current_cost - new_cost) / temp):
                    current_cost = new_cost
                else:
                    y[idx1], y[idx2] = y[idx2], y[idx1]

        temp *= cooling_rate
        if i % 10000 == 0:
            print(f"Iteration {i}, cost {current_cost}")

    return None

